'use client';

import { BarChart3, TrendingDown, TrendingUp } from 'lucide-react';
import { Card, CardTitle, DemoBadge, PageHeader } from '@/components/app/dashboard/kit';
import { cx } from '@/components/app/dashboard/data';
import { DEMO_ANALYTICS } from '@/components/app/dashboard/demo';

// Analytics — all figures are demo data (no metrics warehouse in this local build).
export default function AnalyticsPage() {
  const { kpis, volume, languages, tracks } = DEMO_ANALYTICS;
  const peak = Math.max(...volume);

  return (
    <div>
      <PageHeader title="Analytics" sub="Call volume, outcomes, and language mix." actions={<DemoBadge />} />

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        {kpis.map((k) => (
          <Card key={k.label} className="p-4 sm:p-5">
            <div className="text-muted-foreground text-xs font-medium">{k.label}</div>
            <div className="mt-2 text-2xl font-bold tabular-nums">{k.value}</div>
            <div
              className={cx(
                'mt-1 inline-flex items-center gap-1 text-xs font-medium',
                k.up ? 'text-emerald-600 dark:text-emerald-400' : 'text-muted-foreground'
              )}
            >
              {k.up ? <TrendingUp className="size-3.5" /> : <TrendingDown className="size-3.5" />}
              {k.delta}
            </div>
          </Card>
        ))}
      </div>

      <Card className="mb-6">
        <CardTitle icon={BarChart3}>Call volume · last 14 days</CardTitle>
        <div className="flex h-40 items-end gap-1.5 sm:gap-2">
          {volume.map((v, i) => (
            <div key={i} className="group flex flex-1 flex-col items-center gap-1.5">
              <span className="text-muted-foreground text-[10px] opacity-0 transition-opacity group-hover:opacity-100">
                {v}
              </span>
              <div
                className="bg-primary/80 hover:bg-primary w-full rounded-t transition-colors"
                style={{ height: `${Math.round((v / peak) * 100)}%` }}
                title={`Day ${i + 1}: ${v} calls`}
              />
            </div>
          ))}
        </div>
      </Card>

      <div className="grid gap-4 sm:grid-cols-2">
        <Card>
          <CardTitle>Languages</CardTitle>
          <BarList items={languages} />
        </Card>
        <Card>
          <CardTitle>Tracks</CardTitle>
          <BarList items={tracks} />
        </Card>
      </div>
    </div>
  );
}

// Horizontal proportion bars — no chart lib for five rows.
function BarList({ items }: { items: { label: string; pct: number }[] }) {
  return (
    <ul className="space-y-3">
      {items.map((it) => (
        <li key={it.label}>
          <div className="mb-1 flex items-center justify-between text-sm">
            <span>{it.label}</span>
            <span className="text-muted-foreground tabular-nums">{it.pct}%</span>
          </div>
          <div className="bg-muted h-2 overflow-hidden rounded-full">
            <div className="bg-primary h-full rounded-full" style={{ width: `${it.pct}%` }} />
          </div>
        </li>
      ))}
    </ul>
  );
}

'use client';

import { useState } from 'react';
import { BookOpen, FileStack } from 'lucide-react';
import { Card, DemoBadge, EmptyState, PageHeader, StatusPill } from '@/components/app/dashboard/kit';
import { cx } from '@/components/app/dashboard/data';
import { DEMO_KB } from '@/components/app/dashboard/demo';

const INPUT =
  'border-input bg-background focus-visible:ring-ring/50 h-9 w-full rounded-md border px-3 text-sm outline-none focus-visible:ring-2';

// Knowledge Base — demo data (RAG store not wired in this local build; the agent
// answers from the LLM + shop catalogue today, per the Integrations page).
export default function KnowledgePage() {
  const [query, setQuery] = useState('');
  const q = query.trim().toLowerCase();
  const rows = DEMO_KB.filter((k) => !q || k.title.toLowerCase().includes(q) || k.track.toLowerCase().includes(q));

  return (
    <div>
      <PageHeader
        title="Knowledge Base"
        sub="Reference documents the agent can draw on."
        actions={<DemoBadge />}
      />

      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search documents…"
        className={cx(INPUT, 'mb-5 max-w-md')}
      />

      {rows.length === 0 ? (
        <EmptyState icon={BookOpen} title="No documents match" sub="Try a different search." />
      ) : (
        <div className="grid gap-3 sm:grid-cols-2">
          {rows.map((k) => (
            <Card key={k.id} className="flex items-start gap-3 p-4">
              <span className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-xl">
                <FileStack className="size-5" />
              </span>
              <div className="min-w-0 flex-1">
                <div className="truncate font-medium">{k.title}</div>
                <div className="text-muted-foreground mt-1 flex flex-wrap items-center gap-2 text-xs">
                  <StatusPill tone="info">{k.track}</StatusPill>
                  <span>{k.chunks} chunks</span>
                  <span>· updated {k.updated}</span>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { Bot, Ear, Languages, MessageSquare, Mic, Volume2 } from 'lucide-react';
import { Card, CardTitle, DemoBadge, MetaRow, PageHeader, StatusPill, type Tone } from '@/components/app/dashboard/kit';
import { DEMO_AGENTS } from '@/components/app/dashboard/demo';

// This agent's real pipeline — the actual components backend/src/agent.py runs.
// Not demo: these are the real STT/LLM/TTS/VAD choices baked into the worker.
const PIPELINE: { icon: React.ElementType; label: string; value: string }[] = [
  { icon: Ear, label: 'Speech-to-text', value: 'Deepgram Nova-3 (language=multi)' },
  { icon: MessageSquare, label: 'LLM', value: 'Google Gemini' },
  { icon: Volume2, label: 'Text-to-speech', value: 'Murf Falcon · voice Anisha' },
  { icon: Mic, label: 'Turn detection', value: 'Silero VAD' },
  { icon: Languages, label: 'Languages', value: 'Auto-detected, native script' },
];

const STATUS_TONE: Record<string, Tone> = {
  online: 'success',
  draft: 'neutral',
};

export default function AgentsPage() {
  return (
    <div>
      <PageHeader title="Agent Settings" sub="Voice pipeline configuration and the agent fleet." />

      <Card className="mb-6">
        <CardTitle icon={Bot} right={<StatusPill tone="success" pulse>Live pipeline</StatusPill>}>
          This agent · DukaanSaathi
        </CardTitle>
        <dl className="divide-y">
          {PIPELINE.map(({ icon: Icon, label, value }) => (
            <MetaRow key={label} label={label}>
              <span className="inline-flex items-center gap-1.5">
                <Icon className="text-primary size-4" /> {value}
              </span>
            </MetaRow>
          ))}
        </dl>
        <p className="text-muted-foreground mt-4 text-xs leading-5">
          These are the real components the Python worker runs (backend/src/agent.py). Model and
          voice are set in the backend configuration, not editable from this screen.
        </p>
      </Card>

      <div className="mb-3 flex items-center gap-2">
        <h2 className="font-semibold">Fleet</h2>
        <DemoBadge />
      </div>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {DEMO_AGENTS.map((a) => (
          <Card key={a.id} className="p-4">
            <div className="flex items-center gap-2">
              <span className="bg-primary/10 text-primary flex size-9 items-center justify-center rounded-lg">
                <Bot className="size-4" />
              </span>
              <StatusPill tone={STATUS_TONE[a.status] ?? 'neutral'} pulse={a.status === 'online'}>
                {a.status}
              </StatusPill>
            </div>
            <div className="mt-3 font-semibold">{a.name}</div>
            <div className="text-muted-foreground mt-1 text-xs">
              {a.track} · {a.voice}
            </div>
            <div className="text-muted-foreground mt-3 text-xs tabular-nums">
              {a.calls.toLocaleString()} calls handled
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

'use client';

import { CheckCircle2, Circle, KeyRound, Plug } from 'lucide-react';
import { Card, PageHeader, StatusPill, type Tone } from '@/components/app/dashboard/kit';
import { DEMO_INTEGRATIONS, type IntegrationStatus } from '@/components/app/dashboard/demo';

const STATUS_TONE: Record<IntegrationStatus, Tone> = {
  connected: 'success',
  available: 'info',
  'not-configured': 'neutral',
};

const STATUS_LABEL: Record<IntegrationStatus, string> = {
  connected: 'Connected',
  available: 'Available',
  'not-configured': 'Not configured',
};

// Tools & Integrations. `real` splits what THIS build actually runs from what the
// mockup lists aspirationally. Security: API keys are NEVER rendered here — only
// the service name and its live/planned status. Keys live in backend/.env.local.
export default function IntegrationsPage() {
  const active = DEMO_INTEGRATIONS.filter((i) => i.real);
  const planned = DEMO_INTEGRATIONS.filter((i) => !i.real);

  return (
    <div>
      <PageHeader title="Tools & Integrations" sub="Services powering the voice pipeline." />

      <div className="border-primary/20 bg-primary/5 text-foreground/80 mb-6 flex items-start gap-2 rounded-xl border p-4 text-sm">
        <KeyRound className="text-primary mt-0.5 size-4 shrink-0" />
        API keys and secrets are stored server-side in <code className="font-mono text-xs">backend/.env.local</code> and are
        never shown in this dashboard. This page reflects connection status only.
      </div>

      <h2 className="mb-3 flex items-center gap-2 font-semibold">
        <Plug className="text-primary size-4" /> Active in this build
      </h2>
      <div className="mb-8 grid gap-3 sm:grid-cols-2">
        {active.map((i) => (
          <IntegrationCard key={i.name} {...i} />
        ))}
      </div>

      <h2 className="text-muted-foreground mb-3 font-semibold">Planned / available</h2>
      <div className="grid gap-3 sm:grid-cols-2">
        {planned.map((i) => (
          <IntegrationCard key={i.name} {...i} />
        ))}
      </div>
    </div>
  );
}

function IntegrationCard({
  name,
  role,
  status,
}: {
  name: string;
  role: string;
  status: IntegrationStatus;
}) {
  const connected = status === 'connected';
  return (
    <Card className="flex items-start gap-3 p-4">
      <span
        className={
          connected
            ? 'flex size-9 shrink-0 items-center justify-center rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400'
            : 'bg-muted text-muted-foreground flex size-9 shrink-0 items-center justify-center rounded-lg'
        }
      >
        {connected ? <CheckCircle2 className="size-5" /> : <Circle className="size-5" />}
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="font-medium">{name}</span>
          <span className="ml-auto">
            <StatusPill tone={STATUS_TONE[status]} pulse={connected}>
              {STATUS_LABEL[status]}
            </StatusPill>
          </span>
        </div>
        <p className="text-muted-foreground mt-1 text-sm leading-6">{role}</p>
      </div>
    </Card>
  );
}

'use client';

import Link from 'next/link';
import { ArrowLeft, BadgeCheck, ShieldCheck } from 'lucide-react';
import { useLanguage } from '@/components/app/language-provider';
import { Card, PageHeader } from '@/components/app/dashboard/kit';

// Consent policy — the REAL behaviour of the agent's memory: it asks before saving,
// and never stores secrets. Ported from the old dashboard Consent view.
export default function ConsentPage() {
  const { tr } = useLanguage();

  return (
    <div>
      <Link
        href="/dashboard/settings"
        className="text-muted-foreground hover:text-foreground mb-5 inline-flex items-center gap-1.5 text-sm font-medium"
      >
        <ArrowLeft className="size-4" /> {tr.dashName}
      </Link>

      <PageHeader title={tr.coTitle} sub={tr.coSub} />

      <Card>
        <div className="flex items-center gap-2">
          <ShieldCheck className="text-primary size-5" />
          <span className="font-semibold">{tr.coPromptTitle}</span>
        </div>
        <blockquote className="border-primary/30 bg-primary/5 mt-4 rounded-r-lg border-l-4 px-4 py-3">
          <p className="font-medium" lang="hi">
            “क्या मैं यह आपके लिए याद रख लूँ?”
          </p>
          <p className="text-muted-foreground mt-1 text-sm">“May I remember this for you?”</p>
        </blockquote>
      </Card>

      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <Card>
          <BadgeCheck className="text-primary size-5" />
          <div className="mt-3 font-semibold">{tr.coNeverTitle}</div>
          <p className="text-muted-foreground mt-1 text-sm leading-6">{tr.coNeverBody}</p>
        </Card>
        <Card>
          <ShieldCheck className="text-primary size-5" />
          <div className="mt-3 font-semibold">{tr.memConsentTitle}</div>
          <p className="text-muted-foreground mt-1 text-sm leading-6">{tr.coRefuse}</p>
        </Card>
      </div>
    </div>
  );
}
